var Example = class {
  constructor(component, url, title) {
    this.component = component;
    this.url = url;
    this.title = title;
  }
  get HTMLFile() {
    return this.exampleHTMLFile;
  }
  set HTMLFile(file) {
    this.exampleHTMLFile = file;
  }
  get SCSSFile() {
    return this.exampleSCSSFile;
  }
  set SCSSFile(file) {
    this.exampleSCSSFile = file !== "" ? file : "/** No SCSS for this example */";
  }
  get TSFile() {
    return this.exampleTSFile;
  }
  set TSFile(file) {
    this.exampleTSFile = file;
  }
  setFile(doc, ending) {
    switch (ending) {
      case "ts":
        this.TSFile = doc;
        break;
      case "scss":
        this.SCSSFile = doc;
        break;
      default:
        this.HTMLFile = doc;
        break;
    }
  }
  getFile(ending) {
    switch (ending) {
      case "ts":
        return this.TSFile;
      case "scss":
        return this.SCSSFile;
      default:
        return this.HTMLFile;
    }
  }
};

