        \u0275\u0275elementStart(73, "ul")(74, "li")(75, "strong");
        \u0275\u0275text(76, "label");
        \u0275\u0275elementEnd();
        \u0275\u0275text(77, " (required): label displayed in the table (will be translated if possible)");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(78, "li")(79, "strong");
        \u0275\u0275text(80, "dataPropertyName");
        \u0275\u0275elementEnd();
        \u0275\u0275text(81, " (required): property name of the column in the list of data");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(82, "li")(83, "strong");
        \u0275\u0275text(84, "isSortable");
        \u0275\u0275elementEnd();
        \u0275\u0275text(85, " (optional): if true, column will be sortable if false (or null), column will not be sortable");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(86, "li")(87, "strong");
        \u0275\u0275text(88, "isRightAligned");
        \u0275\u0275elementEnd();
        \u0275\u0275text(89, " (optional): if true, column will have its text aligned to the right, if false (or null) to the left ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(90, "li")(91, "strong");
        \u0275\u0275text(92, "transformer");
        \u0275\u0275elementEnd();
        \u0275\u0275text(93, " (optional): if a function is provided, data will be transformed before being displayed (see ");
        \u0275\u0275elementStart(94, "a", 2);
        \u0275\u0275text(95, "Data Transformation Example");
        \u0275\u0275elementEnd();
        \u0275\u0275text(96, " below). If null, data will be displayed as is ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(97, "li")(98, "strong");
        \u0275\u0275text(99, "transformerParams");
        \u0275\u0275elementEnd();
        \u0275\u0275text(100, " (optional): params for transformer function");
        \u0275\u0275elementEnd()()()();
        \u0275\u0275element(101, "example-viewer", 4);
        \u0275\u0275elementStart(102, "a", 2);
        \u0275\u0275text(103, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(104, "section", 5)(105, "h1");
        \u0275\u0275text(106, "Data transformation");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(107, "p");
        \u0275\u0275text(108, " To transform the displayed data you can set the optional properties ");
        \u0275\u0275elementStart(109, "strong");
        \u0275\u0275text(110, "transformer");
        \u0275\u0275elementEnd();
        \u0275\u0275text(111, " and ");
        \u0275\u0275elementStart(112, "strong");
        \u0275\u0275text(113, "transformerParams");
        \u0275\u0275elementEnd();
        \u0275\u0275text(114, " in the column definition. You can supply any function as transformer. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(115, "ul")(116, "li");
        \u0275\u0275text(117, " Example: Custom transformations for the columns ");
        \u0275\u0275elementStart(118, "em");
        \u0275\u0275text(119, "Title");
        \u0275\u0275elementEnd();
        \u0275\u0275text(120, " (translation), ");
        \u0275\u0275elementStart(121, "em");
        \u0275\u0275text(122, "Gender");
        \u0275\u0275elementEnd();
        \u0275\u0275text(123, " (symbol) and ");
        \u0275\u0275elementStart(124, "em");
        \u0275\u0275text(125, "Email");
        \u0275\u0275elementEnd();
        \u0275\u0275text(126, " (uppercase) ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(127, "li");
        \u0275\u0275text(128, " notice that the internal ");
        \u0275\u0275elementStart(129, "strong");
        \u0275\u0275text(130, "sort");
        \u0275\u0275elementEnd();
        \u0275\u0275text(131, " and ");
        \u0275\u0275elementStart(132, "strong");
        \u0275\u0275text(133, "filter");
        \u0275\u0275elementEnd();
        \u0275\u0275text(134, " will always use the ");
        \u0275\u0275elementStart(135, "strong");
        \u0275\u0275text(136, "displayed data");
        \u0275\u0275elementEnd();
        \u0275\u0275text(137, ", not the actual data. (E.g. you will no longer find matches for 'Mr' or 'Mrs' but instead for 'Herr' or 'Frau'.) ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(138, "li")(139, "strong");
        \u0275\u0275text(140, "events");
        \u0275\u0275elementEnd();
        \u0275\u0275text(141, " (like row actions) will still always return the ");
        \u0275\u0275elementStart(142, "strong");
        \u0275\u0275text(143, "actual data");
        \u0275\u0275elementEnd()()();
        \u0275\u0275element(144, "example-viewer", 4);
        \u0275\u0275elementStart(145, "a", 2);
        \u0275\u0275text(146, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(147, "section", 6)(148, "h1");
        \u0275\u0275text(149, "Single mode");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(150, "p");
        \u0275\u0275text(151, " If at least one rowAction exists with type ");
        \u0275\u0275elementStart(152, "strong");
        \u0275\u0275text(153, "SINGLE");
        \u0275\u0275elementEnd();
        \u0275\u0275text(154, " (but no batch action) the table will be displayed in single mode by default. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(155, "ul")(156, "li");
        \u0275\u0275text(157, "All row actions will be available in the action menu of the leftmost column");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(158, "li");
        \u0275\u0275text(159, "Clicking on any row trigger the default action (=the first action)");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(160, "li");
        \u0275\u0275text(161, " Actions with type ");
        \u0275\u0275elementStart(162, "strong");
        \u0275\u0275text(163, "NONE");
        \u0275\u0275elementEnd();
        \u0275\u0275text(164, ' are actions that are independent of rows and will be displayed above the table (example: "CREATE" action) ');
        \u0275\u0275elementEnd()();
        \u0275\u0275element(165, "example-viewer", 4);
        \u0275\u0275elementStart(166, "a", 2);
        \u0275\u0275text(167, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(168, "section", 7)(169, "h1");
        \u0275\u0275text(170, "Batch mode (multiselect)");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(171, "p");
        \u0275\u0275text(172, " If at least one rowAction exists with type ");
        \u0275\u0275elementStart(173, "strong");
        \u0275\u0275text(174, "BATCH");
        \u0275\u0275elementEnd();
        \u0275\u0275text(175, " the table will be displayed in batch mode by default. You can forcefully override the display mode of the table (see example below with button 'BATCH SELECTION' to force switching between BATCH and SINGLE). ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(176, "ul")(177, "li");
        \u0275\u0275text(178, "Clicking on any row will select or unselected the row.");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(179, "li");
        \u0275\u0275text(180, "All rowActions will be displayed above the table (SINGLE, BATCH and NONE).");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(181, "li");
        \u0275\u0275text(182, " The buttons will be disabled if the amount of selected rows does not match the rowAction type of SINGLE (1), BATCH (>0) or NONE (any amount allowed, selection will be ignored) ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(183, "li");
        \u0275\u0275text(184, " Batch actions will have an indicator showing the number of selected rows. SINGLE and NONE have no indicators, as SINGLE actions always affect one row and NONE actions are always independent of selections. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(185, "li");
        \u0275\u0275text(186, "Clicking the checkbox in the header will select all rows of the current page.");
        \u0275\u0275elementEnd()();
        \u0275\u0275element(187, "example-viewer", 4);
        \u0275\u0275elementStart(188, "a", 2);
        \u0275\u0275text(189, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(190, "section", 8)(191, "h1");
        \u0275\u0275text(192, "Asynchronous loading");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(193, "p");
        \u0275\u0275text(194, "Use asynchronous loading if the dataset is very large (so you only load a single page of the data).");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(195, "ul")(196, "li");
        \u0275\u0275text(197, " As the table no longer has all data (only one page of it), it cannot perform any of the following tasks in a meaningful way: filtering, sorting, paging ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(198, "li")(199, "strong");
        \u0275\u0275text(200, "filtering");
        \u0275\u0275elementEnd();
        \u0275\u0275text(201, ": the internal filter is always deactivated; [filterEnabled] will be ignored and is always false; you can create your own filter and load the data accordingly, then update [page] and [tableData] ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(202, "li")(203, "strong");
        \u0275\u0275text(204, "sorting");
        \u0275\u0275elementEnd();
        \u0275\u0275text(205, ": subscribe to sorting changes with ");
        \u0275\u0275elementStart(206, "strong");
        \u0275\u0275text(207, "(sortEvent)");
        \u0275\u0275elementEnd();
        \u0275\u0275text(208, ", load the new page of data from the server, then update [page] and [tableData] ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(209, "li")(210, "strong");
        \u0275\u0275text(211, "paging");
        \u0275\u0275elementEnd();
        \u0275\u0275text(212, ": set the current page with ");
        \u0275\u0275elementStart(213, "strong");
        \u0275\u0275text(214, "[page]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(215, " and subscribe to paging changes with ");
        \u0275\u0275elementStart(216, "strong");
        \u0275\u0275text(217, "(pageEvent)");
        \u0275\u0275elementEnd();
        \u0275\u0275text(218, ", load the new page of data from the server, then update [page] and [tableData] ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(219, "li");
        \u0275\u0275text(220, "While performing tasks you can display a spinner animation by setting ");
        \u0275\u0275elementStart(221, "strong");
        \u0275\u0275text(222, "[loading]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(223, " to true");
        \u0275\u0275elementEnd()();
        \u0275\u0275element(224, "example-viewer", 4);
        \u0275\u0275elementStart(225, "a", 2);
        \u0275\u0275text(226, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(227, "section", 9)(228, "h1");
        \u0275\u0275text(229, "IDs instead of rows");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(230, "p");
        \u0275\u0275text(231, " By default, row actions will return the complete selected rows (actual data, not displayed data) in the event. ");
        \u0275\u0275element(232, "br");
        \u0275\u0275text(233, " If you want events to return IDs instead of full row objects, provide an ID generator function to ");
        \u0275\u0275elementStart(234, "strong");
        \u0275\u0275text(235, "[idGenerator]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(236, " as in the example below. ");
        \u0275\u0275elementEnd();
        \u0275\u0275element(237, "example-viewer", 4);
        \u0275\u0275elementStart(238, "a", 2);
        \u0275\u0275text(239, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(240, "section", 10)(241, "h1");
        \u0275\u0275text(242, "Child rows (limited support)");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(243, "p");
        \u0275\u0275text(244, "It is now possible to mark rows as child rows. For now, child rows only have limited support:");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(245, "ul")(246, "li");
        \u0275\u0275text(247, "no table actions for child rows (ignored in batch and single actions)");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(248, "li");
        \u0275\u0275text(249, " automatic sorting will not work properly (implement own sorting logic or use asnyc datatable with correct sorting in the backend) ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(250, "li");
        \u0275\u0275text(251, " provide ");
        \u0275\u0275elementStart(252, "strong");
        \u0275\u0275text(253, "[idGenerator]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(254, " and ");
        \u0275\u0275elementStart(255, "strong");
        \u0275\u0275text(256, "[parentIdGenerator]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(257, ". All rows having a generated parentId will be treated as child rows ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(258, "li");
        \u0275\u0275text(259, "if more features for child rows are required, feel free to add an issue... or even better: help and create a pull request!");
        \u0275\u0275elementEnd()();
        \u0275\u0275element(260, "example-viewer", 4);
        \u0275\u0275elementStart(261, "a", 2);
        \u0275\u0275text(262, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(263, "section", 11)(264, "h1");
        \u0275\u0275text(265, "Custom column configuration");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(266, "p");
        \u0275\u0275text(267, " If you provide at least one template for ");
        \u0275\u0275elementStart(268, "strong");
        \u0275\u0275text(269, "[columnDefinitionTemplates]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(270, " (default: []), the table will display a button for the user to configure the columns. The template may have a name (if not the name will be USER) and must have a list of all available columns, and all selected columns. On clicking the button a modal will open where the user can chose their selected columns and reorder them with three available actions: SAVE, RESET, and CANCEL. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(271, "p");
        \u0275\u0275text(272, " The dataTable will return a ");
        \u0275\u0275elementStart(273, "strong");
        \u0275\u0275text(274, "(columnConfigurationChanged)");
        \u0275\u0275elementEnd();
        \u0275\u0275text(275, " event with the name of the action, the name of the edited columnDefinitionTemplate (default: USER) and the selected configuration. Subscribe to this event if you want to persist the user's configuration to your storage or database. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(276, "p");
        \u0275\u0275text(277, " The dataTable will return a ");
        \u0275\u0275elementStart(278, "strong");
        \u0275\u0275text(279, "(columnConfigurationChanged)");
        \u0275\u0275elementEnd();
        \u0275\u0275text(280, " event with the name of the action and the selected configuration. Subscribe to this event if you want to persist the user's configuration to your storage or database. ");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(281, "p");
        \u0275\u0275text(282, "If you provide more than one ColumnDefinitionTemplate, the user can choose which template they want to edit.");
        \u0275\u0275elementEnd();
        \u0275\u0275element(283, "example-viewer", 4);
        \u0275\u0275elementStart(284, "a", 2);
        \u0275\u0275text(285, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(286, "section", 12)(287, "h1");
        \u0275\u0275text(288, "Stretch table to parent height");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(289, "p");
        \u0275\u0275text(290, " Set ");
        \u0275\u0275elementStart(291, "strong");
        \u0275\u0275text(292, "[tableClass]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(293, " to ");
        \u0275\u0275elementStart(294, "em");
        \u0275\u0275text(295, "datatable-vertical-stretch-to-parent");
        \u0275\u0275elementEnd();
        \u0275\u0275text(296, " to have the table stretch to the height of its parent (to fill a card or the whole content area. Note that the table has a minimum height and will get a scollbar if it cannot display all of its rows so that the pagination will always be visible. ");
        \u0275\u0275elementEnd();
        \u0275\u0275element(297, "example-viewer", 4);
        \u0275\u0275elementStart(298, "a", 2);
        \u0275\u0275text(299, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(300, "section", 13)(301, "h1");
        \u0275\u0275text(302, "Filter table based on columns");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(303, "p");
        \u0275\u0275text(304, " Use ");
        \u0275\u0275elementStart(305, "strong");
        \u0275\u0275text(306, "[filterMode]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(307, " to ");
        \u0275\u0275elementStart(308, "em");
        \u0275\u0275text(309, "COLUMN_BASED");
        \u0275\u0275elementEnd();
        \u0275\u0275text(310, " to filter a table based on its columns. Furthermore, add the ");
        \u0275\u0275elementStart(311, "strong");
        \u0275\u0275text(312, "isFilterable");
        \u0275\u0275elementEnd();
        \u0275\u0275text(313, " property to each DataTableColumn, which is filterable. The ");
        \u0275\u0275elementStart(314, "strong");
        \u0275\u0275text(315, "filterParams");
        \u0275\u0275elementEnd();
        \u0275\u0275text(316, " property ");
        \u0275\u0275elementStart(317, "strong");
        \u0275\u0275text(318, "filterOptions");
        \u0275\u0275elementEnd();
        \u0275\u0275text(319, " can be used to pass an array of key-value pairs to filter on a predefined set (e.g. enum values). ");
        \u0275\u0275elementEnd();
        \u0275\u0275element(320, "example-viewer", 4);
        \u0275\u0275elementStart(321, "a", 2);
        \u0275\u0275text(322, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(323, "section", 14)(324, "h1");
        \u0275\u0275text(325, "Stateful datatable");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(326, "p");
        \u0275\u0275text(327, " Set ");
        \u0275\u0275elementStart(328, "strong");
        \u0275\u0275text(329, "[persistenceConfig]");
        \u0275\u0275elementEnd();
        \u0275\u0275text(330, " to ");
        \u0275\u0275elementStart(331, "em");
        \u0275\u0275text(332, "persistSort: true, persistFilter: true, persistePageSize: true");
        \u0275\u0275elementEnd();
        \u0275\u0275text(333, " to persist the datatables sort, filter and pageSize state. Override the ");
        \u0275\u0275elementStart(334, "strong");
        \u0275\u0275text(335, "DataTablePersistenceService");
        \u0275\u0275elementEnd();
        \u0275\u0275text(336, " class and inject it via ");
        \u0275\u0275elementStart(337, "strong");
        \u0275\u0275text(338, "DATA_TABLE_PERSISTENCE_SERVICE_PROVIDER");
        \u0275\u0275elementEnd();
        \u0275\u0275text(339, " to provide a custom implementation. ");
        \u0275\u0275elementEnd();
        \u0275\u0275element(340, "example-viewer", 4);
        \u0275\u0275elementStart(341, "a", 2);
        \u0275\u0275text(342, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(343, "section", 15)(344, "h1");
        \u0275\u0275text(345, "Cell templates for custom cell definitions");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(346, "p");
        \u0275\u0275text(347, " Use ");
        \u0275\u0275elementStart(348, "strong");
        \u0275\u0275text(349, "madColumnDef");
        \u0275\u0275elementEnd();
        \u0275\u0275text(350, " to define a new columnDefinition using the ");
        \u0275\u0275elementStart(351, "strong");
        \u0275\u0275text(352, "id");
        \u0275\u0275elementEnd();
        \u0275\u0275text(353, " of the DataTableColumn. Use ");
        \u0275\u0275elementStart(354, "strong");
        \u0275\u0275text(355, "madCellDef");
        \u0275\u0275elementEnd();
        \u0275\u0275text(356, " to define a new cellDefinition for the corresponding madColumnDef. Use the ");
        \u0275\u0275elementStart(357, "em");
        \u0275\u0275text(358, "let element");
        \u0275\u0275elementEnd();
        \u0275\u0275text(359, " syntax inside the ");
        \u0275\u0275elementStart(360, "strong");
        \u0275\u0275text(361, "madCellDef");
        \u0275\u0275elementEnd();
        \u0275\u0275text(362, " directive to retrieve the element of the current row, to access its data. ");
        \u0275\u0275elementEnd();
        \u0275\u0275element(363, "example-viewer", 4);
        \u0275\u0275elementStart(364, "a", 2);
        \u0275\u0275text(365, "Back to overview");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(366, "section", 16)(367, "h1");
        \u0275\u0275text(368, "Template to make a row expandable");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(369, "p");
        \u0275\u0275text(370, " Use ");
        \u0275\u0275elementStart(371, "strong");
